/**
 * VR locomotion math — the Babylon-FREE core.
 *
 *
 * The pure snap/smooth-turn + config-resolution logic behind controlflags-driven
 * VR locomotion. ZERO Babylon/WebXR imports — imported ONLY by the code-split
 * `xrChunk.ts` (and the unit tests), so it rides the split chunk and never lands
 * in the main first-paint bundle (like `worldApiPrelude.ts` rides the sandbox
 * chunk). Unit-testable with plain numbers — no headset needed.
 *
 * SEMANTICS:
 * - `turn-locomotion` snap/smooth/none, with the comfort default SNAP. Snap is
 *   a discrete, debounced step and smooth a continuous rate, the same model as
 *   the XR Interaction Toolkit's `SnapTurnProvider` / `ContinuousTurnProvider`;
 *   both are implemented natively here, since no such toolkit exists in a
 *   browser.
 * - `joystick-motion` boolean, with the comfort default OFF.
 *
 * Naming: neutral/veml — `vrLocomotion`, no `webverse`-branded
 * construct an author or another runtime implementer would touch.
 */

/** Resolved per-world VR locomotion configuration (from `controlflags`). */
export interface VrLocomotionConfig {
  /** Turn style: snap (discrete debounced steps) / smooth (continuous rate) / none. */
  turn: 'snap' | 'smooth' | 'none';
  /** Stick translation of the rig (through the desktop grounding/collision path). */
  joystickMotion: boolean;
}

// --- Turn constants (v4-native magnitudes; XRIT defaults are the reference) ---
/** Snap-turn discrete step: 45° (XRIT `SnapTurnProvider.turnAmount` default). */
export const SNAP_TURN_ANGLE_RAD = Math.PI / 4;
/** Stick magnitude to TRIGGER a snap (upper hysteresis threshold). */
export const SNAP_ACTIVATE = 0.7;
/** Stick magnitude to RE-ARM a snap (lower hysteresis threshold — one flick = one snap). */
export const SNAP_RELEASE = 0.3;
/** Smooth-turn continuous rate: 90°/s (a comfortable continuous yaw). */
export const SMOOTH_TURN_SPEED_RAD_PER_S = (90 * Math.PI) / 180;
/** Turn-stick deadzone below which smooth turn is idle. */
export const TURN_DEADZONE = 0.15;
/** Motion-stick deadzone below which no translation occurs. */
export const MOTION_DEADZONE = 0.15;
/** VR walk speed — matches the desktop `DEFAULT_WALK_SPEED_MPS` (3 m/s). */
export const VR_WALK_SPEED_MPS = 3;

/** A finite-guarded number (NaN/Infinity → 0). */
function finiteOrZero(v: number): number {
  return Number.isFinite(v) ? v : 0;
}

/**
 * Resolve the parsed `controlFlags` into a VR locomotion config with comfort
 * defaults. `turnLocomotion` is lowercased + quote-stripped, so `"Smooth"` and
 * `smooth` agree; an ABSENT or UNKNOWN value defaults to `snap` (the
 * comfort-safe baseline — an unknown value never crashes). `joystickMotion`
 * defaults to `false`.
 */
export function resolveVrLocomotionConfig(controlFlags?: {
  turnLocomotion?: string;
  joystickMotion?: boolean;
}): VrLocomotionConfig {
  const raw =
    typeof controlFlags?.turnLocomotion === 'string'
      ? controlFlags.turnLocomotion.toLowerCase().replace(/"/g, '').trim()
      : '';
  let turn: VrLocomotionConfig['turn'];
  if (raw === 'smooth') turn = 'smooth';
  else if (raw === 'none') turn = 'none';
  else turn = 'snap'; // 'snap' + absent + unknown → snap (comfort default)
  return { turn, joystickMotion: controlFlags?.joystickMotion === true };
}

/**
 * A turn controller: given the turn-stick x and a tick dt, returns the yaw
 * delta in radians to apply to the XR rig (0 most ticks). Stateful for snap
 * (debounce); stateless for smooth/none.
 */
export interface TurnController {
  update(turnStickX: number, dtS: number): number;
}

/**
 * Snap turn — ONE debounced discrete step per stick-flick. Armed while the
 * stick is below `SNAP_RELEASE`; crossing `SNAP_ACTIVATE` emits one
 * `±SNAP_TURN_ANGLE_RAD` and DISARMS until the stick returns below
 * `SNAP_RELEASE` (hysteresis → no repeat-fire while held, no chatter at the
 * threshold). Mirrors XRIT `SnapTurnProvider`'s activate/deactivate debounce.
 */
export function createSnapTurn(): TurnController {
  let armed = true;
  return {
    update(turnStickX: number): number {
      const x = finiteOrZero(turnStickX);
      const mag = Math.abs(x);
      if (armed && mag > SNAP_ACTIVATE) {
        armed = false;
        return Math.sign(x) * SNAP_TURN_ANGLE_RAD;
      }
      if (mag < SNAP_RELEASE) armed = true;
      return 0;
    },
  };
}

/**
 * Smooth turn — a continuous yaw rate proportional to the stick beyond the
 * deadzone. Mirrors XRIT `ContinuousTurnProvider`.
 */
export function createSmoothTurn(): TurnController {
  return {
    update(turnStickX: number, dtS: number): number {
      const x = finiteOrZero(turnStickX);
      const dt = finiteOrZero(dtS);
      if (Math.abs(x) < TURN_DEADZONE) return 0;
      return SMOOTH_TURN_SPEED_RAD_PER_S * x * dt;
    },
  };
}

/** Build the turn controller for a resolved config (`none` → always 0). */
export function createTurnController(config: VrLocomotionConfig): TurnController {
  if (config.turn === 'smooth') return createSmoothTurn();
  if (config.turn === 'none') return { update: () => 0 };
  return createSnapTurn();
}

/**
 * Apply the motion-stick deadzone: a stick vector whose magnitude is below
 * `MOTION_DEADZONE` reads as zero (avoids drift from a resting stick).
 */
export function applyMotionDeadzone(x: number, y: number): { x: number; y: number } {
  const fx = finiteOrZero(x);
  const fy = finiteOrZero(y);
  if (Math.hypot(fx, fy) < MOTION_DEADZONE) return { x: 0, y: 0 };
  return { x: fx, y: fy };
}
