/**
 * VR pointer logic — the Babylon-FREE core.
 *
 *
 * The pure per-hand VR-pointer orchestration behind controlflags-driven VR
 * interaction: resolve `left-vr-pointer`/`right-vr-pointer` into per-hand modes
 * (`none`/`teleport`/`ui`), then each presenting frame dispatch each hand's ray
 * by its mode — `ui` picks a PORTAL (via the desktop's own `pickPortal`) and
 * the trigger navigates via the SHARED history stack; `teleport` picks a GROUND
 * point (walkable meshes ONLY) and the trigger `teleportFeet`s the rig there.
 *
 * ZERO Babylon/WebXR imports — every Babylon-touching collaborator (the `Ray`
 * factory, `pickPortal`, `pickGroundPoint`, `navigate`, `teleport`, and the
 * in-world affordance) is INJECTED, so this module is unit-testable with plain
 * fakes AND with the REAL `pickPortal` (proving the VR portal pick is the SAME
 * desktop raycast, not a fork). Imported ONLY by the code-split `xrChunk.ts` (and
 * the unit tests), so it rides the split chunk and never lands in main
 * first-paint (like `vrLocomotion.ts`).
 *
 * SEMANTICS:
 * - `leftvrpointer`/`rightvrpointer` each select none/teleport/ui per hand,
 *   with the defaults left none / right ui.
 * - Teleport = an XR ray → ground → teleport-on-select; UI = a ray → select.
 *
 * Naming: neutral/veml — `vrPointer`, no `webverse`-branded
 * construct an author or another runtime implementer would touch.
 */

/** A hand's resolved pointer mode (from `controlflags`). */
export type VrPointerMode = 'none' | 'teleport' | 'ui';

/** Which controller a per-frame pointer read came from. */
export type VrPointerHand = 'left' | 'right';

/** Per-hand resolved VR pointer configuration. */
export interface VrPointerConfig {
  left: VrPointerMode;
  right: VrPointerMode;
}

/** A plain 3-vector crossing the pure↔Babylon seam (no Babylon type). */
export interface VrVec3 {
  x: number;
  y: number;
  z: number;
}

/**
 * A per-hand per-frame pointer snapshot the chunk reads off the raw XR frame
 * (the controller `targetRaySpace` pose → origin + forward, converted to Babylon
 * world space) + the raw gamepad trigger. `present` is false when that hand has
 * no live controller this frame (its affordance is cleared, its trigger idle).
 */
export interface VrPointerHandFrame {
  hand: VrPointerHand;
  origin: VrVec3;
  direction: VrVec3;
  trigger: boolean;
  present: boolean;
}

// --- Injected structural collaborators (Babylon-free from this module's view) ---

/** An opaque aim ray (a Babylon `Ray` in the chunk; opaque here). */
export type VrRay = unknown;

/** The minimal portal-pick shape this module reads (a desktop `PortalPick`). */
export interface VrPortalPick {
  candidate: { link: { resolvedHref: string; label: string }; meshes: readonly unknown[] };
  mesh: unknown;
}

/** The minimal portal candidate shape (a desktop `PortalEntry`). */
export interface VrPortalCandidate {
  link: { resolvedHref: string; label: string };
  meshes: readonly unknown[];
}

/** The minimal ground-pick shape this module reads (a `GroundPick`). */
export interface VrGroundPick {
  point: VrVec3;
  mesh: unknown;
}

/** The in-world affordance surface (built by `vrPointerAffordance.ts`). */
export interface VrPointerAffordanceLike {
  showRay(hand: VrPointerHand, origin: VrVec3, direction: VrVec3, length: number): void;
  hideRay(hand: VrPointerHand): void;
  showPortalFocus(hand: VrPointerHand, mesh: unknown, label: string): void;
  clearPortalFocus(hand: VrPointerHand): void;
  showTeleportTarget(hand: VrPointerHand, point: VrVec3, valid: boolean): void;
  hideTeleportTarget(hand: VrPointerHand): void;
}

/** Everything `createVrPointer` needs — all Babylon-touching bits INJECTED. */
export interface VrPointerDeps {
  config: VrPointerConfig;
  /** Build an aim ray (a Babylon `Ray` in the chunk). Keeps this module Babylon-free. */
  makeRay(origin: VrVec3, direction: VrVec3, length: number): VrRay;
  /** The REAL desktop `pickPortal` (injected → proves reuse, not a fork). */
  pickPortal(ray: VrRay, candidates: readonly VrPortalCandidate[]): VrPortalPick | null;
  /** The active world's portal candidates (`registry.portals()`). */
  getPortals(): readonly VrPortalCandidate[];
  /** The REAL `pickGroundPoint` (SAME raycast core as `pickPortal`). */
  pickGround(ray: VrRay, meshes: readonly unknown[]): VrGroundPick | null;
  /** The active world's WALKABLE-GROUND meshes ONLY (sky/backdrop excluded). */
  getWalkableMeshes(): readonly unknown[];
  /** Navigate via the SAME NavigationController + shared history as desktop. */
  navigate(href: string): void;
  /** Teleport the controller/rig feet to a ground point. */
  teleport(point: VrVec3): void;
  /**
   * The entity under a `ui` ray when no portal is, by id (the desktop
   * click's candidate set). Absent: the trigger presses nothing but portals.
   */
  pickEntity?(ray: VrRay): string | null;
  /** Run that entity's on-click, as a desktop click does. */
  clickEntity?(id: string): void;
  /** The in-world affordance (highlight + label + reticle + optional laser). */
  affordance: VrPointerAffordanceLike;
  /** Aim reach for the `ui` portal ray (metres). */
  reachPortalM: number;
  /** Aim reach for the `teleport` ground ray (metres). */
  reachTeleportM: number;
}

/** The per-hand VR pointer driver the chunk ticks each presenting frame. */
export interface VrPointer {
  /** Dispatch this frame's per-hand pointer reads (pick + affordance + select). */
  update(hands: readonly VrPointerHandFrame[]): void;
  /** Clear all affordance + focus state (on exit / teardown). */
  clear(): void;
}

/** The default hand mode when a flag is absent. */
const DEFAULT_MODE: VrPointerConfig = { left: 'none', right: 'ui' };

/** Normalize a single flag value → a mode, falling back to `dflt` on absent/unknown. */
function resolveMode(raw: string | undefined, dflt: VrPointerMode): VrPointerMode {
  if (typeof raw !== 'string') return dflt;
  const v = raw.toLowerCase().replace(/"/g, '').trim();
  if (v === 'ui') return 'ui';
  if (v === 'teleport') return 'teleport';
  if (v === 'none') return 'none';
  return dflt; // unknown → the hand's comfort default (no throw)
}

/**
 * Resolve the parsed `controlFlags` into per-hand pointer modes with their
 * defaults. `leftVrPointer`/`rightVrPointer` are lowercased + quote-stripped,
 * so `"UI"` and `ui` agree; an ABSENT or UNKNOWN value defaults to that hand's
 * baseline — **left `none`, right `ui`**. Independent per hand.
 */
export function resolveVrPointerConfig(controlFlags?: {
  leftVrPointer?: string;
  rightVrPointer?: string;
}): VrPointerConfig {
  return {
    left: resolveMode(controlFlags?.leftVrPointer, DEFAULT_MODE.left),
    right: resolveMode(controlFlags?.rightVrPointer, DEFAULT_MODE.right),
  };
}

/** Per-hand mutable pointer state (focus + last-frame trigger for edge detection). */
interface HandState {
  prevTrigger: boolean;
  focusedHref: string | null;
  teleportPoint: VrVec3 | null;
}

/**
 * Build the per-hand VR pointer driver. Each `update(hands)` call, for each
 * hand: if the hand's mode is `none` or the controller is absent, clear its
 * affordance; otherwise cast a ray (via the injected `makeRay`) and dispatch by
 * mode — `ui` → `pickPortal` + highlight/label + trigger-navigate; `teleport` →
 * `pickGroundPoint` + reticle + trigger-teleport. The trigger is edge-detected
 * per hand (a HELD trigger fires ONE select).
 */
export function createVrPointer(deps: VrPointerDeps): VrPointer {
  const state: Record<VrPointerHand, HandState> = {
    left: { prevTrigger: false, focusedHref: null, teleportPoint: null },
    right: { prevTrigger: false, focusedHref: null, teleportPoint: null },
  };

  const clearHand = (hand: VrPointerHand): void => {
    const s = state[hand];
    if (s.focusedHref !== null) {
      deps.affordance.clearPortalFocus(hand);
      s.focusedHref = null;
    }
    if (s.teleportPoint !== null) {
      deps.affordance.hideTeleportTarget(hand);
      s.teleportPoint = null;
    }
    deps.affordance.hideRay(hand);
  };

  const updateHand = (frame: VrPointerHandFrame): void => {
    const hand = frame.hand;
    const s = state[hand];
    const mode = deps.config[hand];

    // `none` or no live controller → idle: clear affordance, keep the trigger
    // state fresh so a re-enabled hand does not fire a stale edge.
    if (mode === 'none' || !frame.present) {
      clearHand(hand);
      s.prevTrigger = frame.trigger;
      return;
    }

    const reach = mode === 'teleport' ? deps.reachTeleportM : deps.reachPortalM;
    const ray = deps.makeRay(frame.origin, frame.direction, reach);
    deps.affordance.showRay(hand, frame.origin, frame.direction, reach);

    const triggerRising = frame.trigger && !s.prevTrigger;

    if (mode === 'ui') {
      if (s.teleportPoint !== null) {
        deps.affordance.hideTeleportTarget(hand);
        s.teleportPoint = null;
      }
      const pick = deps.pickPortal(ray, deps.getPortals());
      if (pick) {
        const link = pick.candidate.link;
        const label = link.label !== '' ? link.label : link.resolvedHref;
        deps.affordance.showPortalFocus(hand, pick.mesh, label);
        s.focusedHref = link.resolvedHref;
      } else if (s.focusedHref !== null) {
        deps.affordance.clearPortalFocus(hand);
        s.focusedHref = null;
      }
      // Trigger-SELECT → navigate via the SAME seam + shared history as desktop.
      if (triggerRising && s.focusedHref !== null) {
        deps.navigate(s.focusedHref);
      } else if (triggerRising && deps.pickEntity && deps.clickEntity) {
        // No portal under the ray: a button, or any entity with an on-click,
        // is pressed the way a mouse click presses it.
        const id = deps.pickEntity(ray);
        if (id !== null) deps.clickEntity(id);
      }
    } else {
      // teleport
      if (s.focusedHref !== null) {
        deps.affordance.clearPortalFocus(hand);
        s.focusedHref = null;
      }
      const ground = deps.pickGround(ray, deps.getWalkableMeshes());
      if (ground) {
        const p: VrVec3 = { x: ground.point.x, y: ground.point.y, z: ground.point.z };
        deps.affordance.showTeleportTarget(hand, p, true);
        s.teleportPoint = p;
      } else if (s.teleportPoint !== null) {
        deps.affordance.hideTeleportTarget(hand);
        s.teleportPoint = null;
      }
      // Trigger-SELECT → teleport the rig to the ground point.
      if (triggerRising && s.teleportPoint !== null) {
        deps.teleport(s.teleportPoint);
      }
    }

    s.prevTrigger = frame.trigger;
  };

  return {
    update(hands: readonly VrPointerHandFrame[]): void {
      for (const frame of hands) updateHand(frame);
    },
    clear(): void {
      clearHand('left');
      clearHand('right');
      state.left.prevTrigger = false;
      state.right.prevTrigger = false;
    },
  };
}
