/**
 * WebXR chunk — the code-split immersive-vr entry + controlflags-driven VR
 * locomotion.
 *
 *
 * This module is the ONLY legal import site for `@babylonjs/core/XR/*`. It is
 * loaded EXCLUSIVELY via dynamic `import()` (the default `XrChunkLoader` in
 * `xrTypes.ts`; reached from `main.ts` only when Enter VR is PRESSED) — a
 * desktop/mobile visitor who never enters VR does NOT pay the WebXR bytes at
 * first paint (the code-split both-directions is proven by the e2e). A
 * STATIC import of this module from any main-bundle module would pull the
 * WebXR stack into first paint with NO lint catching it (the shader-import
 * guard is Babylon-*shader*-specific and WebXR imports NO materials/shaders) —
 * so CODE REVIEW + the e2e both-directions + the budget are the guards.
 *
 * WHY the LOW-LEVEL helper: `WebXRExperienceHelper` +
 * `WebXRSessionManager` + `WebXRCamera` import ONLY cameras/math/observable/
 * engine-abstraction/WebGL-layer — NO `Materials/`, NO `/Shaders`, NO loaders
 * — so the shader-import manifest is BYTE-UNCHANGED.
 *
 * WHY the RAW WebXR gamepad, NOT `webXRInput`/`motionController`: VR
 * locomotion reads axes/buttons off
 * `sessionManager.session.inputSources[*].gamepad` (the xr-standard mapping) —
 * it does NOT import `@babylonjs/core/XR/webXRInput` + the motion-controller
 * profile loader (which lazily fetches controller-model glTF from an ONLINE
 * repository — a third-party network dependency, and a risk to the shader
 * manifest). So locomotion adds NO new `@babylonjs/core/XR/*` import → the
 * manifest stays byte-unchanged BY CONSTRUCTION.
 *
 * WHY WebGL2 only: Babylon 9.15 presents WebXR via
 * `XRWebGLLayer` over a `webgl2`/`webgl` context ONLY; `main.ts` gates entry on
 * `engineKind === 'webgl2'`, so this chunk is only reached on a WebGL2 session.
 */
import { Quaternion, Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Ray } from '@babylonjs/core/Culling/ray.core';
import { WebXRExperienceHelper } from '@babylonjs/core/XR/webXRExperienceHelper';
import { WebXRState } from '@babylonjs/core/XR/webXRTypes';
import type { Scene } from '@babylonjs/core/scene';
import type { WebXRCamera } from '@babylonjs/core/XR/webXRCamera';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import { computeHorizontalMove } from '../controller/firstPersonController';
import {
  pickPortal,
  pickGroundPoint,
  PORTAL_MAX_REACH_M,
  TELEPORT_MAX_REACH_M,
  type PortalCandidate,
} from '../interaction/portalPicker';
import type { ImmersiveSessionController, XrInputFrame, XrSessionOptions, XrVec3 } from './xrTypes';
import { wireImmersiveSession, type XrHelperLike } from './immersiveSession';
import {
  applyMotionDeadzone,
  createTurnController,
  resolveVrLocomotionConfig,
  VR_WALK_SPEED_MPS,
} from './vrLocomotion';
import {
  createVrPointer,
  resolveVrPointerConfig,
  type VrGroundPick,
  type VrPointerAffordanceLike,
  type VrPointerHandFrame,
  type VrPortalCandidate,
  type VrPortalPick,
  type VrRay,
  type VrVec3,
} from './vrPointer';

/**
 * A no-op affordance — used only if `main.ts` did not wire
 * `createPointerAffordance` (e.g. a bare structural caller). The real in-world
 * affordance is built in the MAIN bundle (`createVrPointerAffordance`) and
 * injected via `options.createPointerAffordance`, so this chunk carries no
 * Materials import of its own.
 */
const NOOP_AFFORDANCE: VrPointerAffordanceLike = {
  showRay: () => {},
  hideRay: () => {},
  showPortalFocus: () => {},
  clearPortalFocus: () => {},
  showTeleportTarget: () => {},
  hideTeleportTarget: () => {},
};

// Structural WebXR shapes — the ambient `XRSession`/`XRInputSource` DOM types
// are NOT in lib.dom (no `@types/webxr`), so name them structurally (the same
// posture as `XrHelperLike` in immersiveSession.ts). `Gamepad`/`GamepadButton`
// ARE standard lib.dom types, reused here structurally too.
interface XrGamepadLike {
  axes?: ReadonlyArray<number>;
  buttons?: ReadonlyArray<{ pressed: boolean }>;
}
interface XrInputSourceLike {
  handedness?: string;
  gamepad?: XrGamepadLike | null;
  // The controller pointing-ray space (per the WebXR spec). Opaque
  // here; passed to `frame.getPose`.
  targetRaySpace?: unknown;
}
interface XrSessionLike {
  inputSources?: Iterable<XrInputSourceLike>;
}
// The per-frame pose of a controller's targetRaySpace (WebXR
// `XRFrame.getPose`). `transform.position` = the ray origin; `transform.
// orientation` (a quaternion) rotates the WebXR forward (-Z) into the ray
// direction. Structural (no `@types/webxr`).
interface XrPoseLike {
  transform?: {
    position?: { x: number; y: number; z: number };
    orientation?: { x: number; y: number; z: number; w: number };
  };
}
interface XrFrameLike {
  getPose(space: unknown, base: unknown): XrPoseLike | null | undefined;
}
interface XrSessionManagerLike {
  session?: XrSessionLike | null;
  currentFrame?: XrFrameLike | null;
  referenceSpace?: unknown;
}

/**
 * Read the per-hand VR POINTER frames off the raw XR frame. For each `inputSource`, the controller's pointing pose comes from
 * `currentFrame.getPose(inputSource.targetRaySpace, referenceSpace)`: the pose
 * `position` is the ray ORIGIN and the pose `orientation` quaternion rotates the
 * WebXR forward (`0,0,-1`) into the ray DIRECTION (converted to Babylon world
 * space via the reference-space pose — the EXACT physical-controller→world
 * alignment is a MANUAL-verify concern, not headless-drivable; do NOT improvise
 * a second transform on top of it). The per-hand trigger (raw
 * gamepad `buttons[0]`) drives the trigger-select edge in `vrPointer`. Returns
 * an empty list when there is no live frame/session (headless / between frames).
 */
const ZERO_VEC: VrVec3 = { x: 0, y: 0, z: 0 };
const FORWARD_VEC: VrVec3 = { x: 0, y: 0, z: -1 };
function readXrPointerHands(mgr: XrSessionManagerLike | undefined | null): VrPointerHandFrame[] {
  if (!mgr || !mgr.session || !mgr.session.inputSources || !mgr.currentFrame || !mgr.referenceSpace) {
    return [];
  }
  const frame = mgr.currentFrame;
  const refSpace = mgr.referenceSpace;
  const out: VrPointerHandFrame[] = [];
  for (const src of mgr.session.inputSources) {
    const hand = src.handedness === 'left' ? 'left' : src.handedness === 'right' ? 'right' : null;
    if (hand === null || !src.targetRaySpace) continue;
    // A hand listed but UNTRACKED this frame (null pose / no transform) → emit an
    // ABSENT frame so the pointer CLEARS its affordance (no stuck highlight/
    // reticle/label when tracking drops), rather than omitting the hand (which
    // would freeze its last visuals in-world).
    const pose = frame.getPose(src.targetRaySpace, refSpace);
    const pos = pose?.transform?.position;
    const ori = pose?.transform?.orientation;
    if (!pos || !ori) {
      out.push({ hand, origin: ZERO_VEC, direction: FORWARD_VEC, trigger: false, present: false });
      continue;
    }
    const q = new Quaternion(ori.x, ori.y, ori.z, ori.w);
    const dir = new Vector3(0, 0, -1).applyRotationQuaternion(q).normalize();
    // A malformed/corrupt pose (non-finite origin or direction) → ABSENT, so no
    // `NaN` ray is ever cast (defense-in-depth with pickGroundPoint's finite
    // guard — a `NaN` teleport target would poison the reference space).
    if (
      !Number.isFinite(pos.x) || !Number.isFinite(pos.y) || !Number.isFinite(pos.z) ||
      !Number.isFinite(dir.x) || !Number.isFinite(dir.y) || !Number.isFinite(dir.z)
    ) {
      out.push({ hand, origin: ZERO_VEC, direction: FORWARD_VEC, trigger: false, present: false });
      continue;
    }
    const buttons = src.gamepad?.buttons ?? [];
    const trigger = buttons.length > 0 && buttons[0]!.pressed === true;
    out.push({
      hand,
      origin: { x: pos.x, y: pos.y, z: pos.z },
      direction: { x: dir.x, y: dir.y, z: dir.z },
      trigger,
      present: true,
    });
  }
  return out;
}

/**
 * Read a per-frame `XrInputFrame` off the raw WebXR gamepads. Iterates
 * the live session's `inputSources`, selecting by `handedness` (left = motion,
 * right = turn). The xr-standard gamepad mapping: `axes[2]/[3]` = thumbstick
 * (falling back to `[0]/[1]` when the pair is absent — e.g. trackpad-only
 * devices); `buttons[0]` = trigger (select), `buttons[1]` = squeeze (grip).
 * Returns `null` when no live session (headless / between frames).
 */
function readXrInputFrame(session: XrSessionLike | undefined | null): XrInputFrame | null {
  if (!session || !session.inputSources) return null;
  const frame: XrInputFrame = {
    leftStick: { x: 0, y: 0 },
    rightStick: { x: 0, y: 0 },
    trigger: false,
    grip: false,
  };
  for (const src of session.inputSources) {
    const pad = src.gamepad;
    if (!pad) continue;
    const axes = pad.axes ?? [];
    // Prefer the thumbstick pair (axes[2],[3]); fall back to axes[0],[1].
    const sx = axes.length >= 4 ? axes[2] : (axes[0] ?? 0);
    const sy = axes.length >= 4 ? axes[3] : (axes[1] ?? 0);
    const buttons = pad.buttons ?? [];
    const pressed = (i: number): boolean => buttons.length > i && buttons[i]!.pressed === true;
    if (src.handedness === 'right') {
      frame.rightStick = { x: sx ?? 0, y: sy ?? 0 };
    } else {
      // 'left' or 'none'/unknown → treat as the motion hand.
      frame.leftStick = { x: sx ?? 0, y: sy ?? 0 };
    }
    // Either controller's trigger/grip counts (a single-controller session
    // still drives select/squeeze).
    if (pressed(0)) frame.trigger = true;
    if (pressed(1)) frame.grip = true;
  }
  return frame;
}

/**
 * Create + wire an immersive-vr session controller for the active scene, with
 * the VR locomotion tick. `WebXRExperienceHelper.CreateAsync` builds
 * the session manager + WebXRCamera; `wireImmersiveSession` owns the enter/exit/
 * position/teardown logic (the Babylon-free core) and calls back into
 * `driveLocomotion` (below) each presenting frame.
 */
export async function createImmersiveSession(
  options: XrSessionOptions,
): Promise<ImmersiveSessionController> {
  const helper = await WebXRExperienceHelper.CreateAsync(options.scene as Scene);

  // Resolve the VR locomotion config from the world's parsed controlflags at
  // enter (comfort defaults inside `resolveVrLocomotionConfig`). The session is
  // bound to the current world (exit-on-nav disposes it on a swap), so the
  // config is stable for this session's lifetime.
  const config = resolveVrLocomotionConfig(options.getControlFlags?.());
  const turnController = createTurnController(config);

  // The VR pointer (per-hand `ui`/`teleport`/`none`). The affordance
  // (in-world highlight + label + reticle) lives in the scene; the pure pointer
  // logic (`vrPointer`) is driven with the REAL desktop `pickPortal` + the
  // `pickGroundPoint` sibling + the navigate/teleport seams — no forked
  // raycaster, no second nav path.
  const pointerConfig = resolveVrPointerConfig(options.getControlFlags?.());
  const affordance = options.createPointerAffordance?.(options.scene) ?? NOOP_AFFORDANCE;
  // Teleport — move the desktop controller/rig feet to the ground point,
  // then re-base the XR camera by the collision-resolved feet DELTA (the same
  // rig↔feetPosition idiom as locomotion) so the headset jumps there and flat-screen exit
  // continuity stays correct.
  const teleport = (point: VrVec3): void => {
    if (!options.teleportFeetTo || !options.getFeetPosition) return;
    // Never teleport to a non-finite target (belt-and-suspenders with the
    // pickGroundPoint + readXrPointerHands guards): a `NaN`/`Infinity` feet
    // position would propagate through teleportFeet into the XR reference-space
    // re-base below and corrupt the whole session (no void teleport).
    if (!Number.isFinite(point.x) || !Number.isFinite(point.y) || !Number.isFinite(point.z)) return;
    const before = options.getFeetPosition();
    options.teleportFeetTo(point.x, point.y, point.z);
    const after = options.getFeetPosition();
    const camera = helper.camera as WebXRCamera;
    camera.position.addInPlaceFromFloats(after.x - before.x, after.y - before.y, after.z - before.z);
  };
  const vrPointer = createVrPointer({
    config: pointerConfig,
    makeRay: (origin, direction, length): VrRay =>
      new Ray(
        new Vector3(origin.x, origin.y, origin.z),
        new Vector3(direction.x, direction.y, direction.z).normalize(),
        length,
      ),
    // The REAL desktop pickPortal (adapter cast — same raycast, not a fork).
    pickPortal: (ray, candidates): VrPortalPick | null =>
      pickPortal(ray as Ray, candidates as unknown as PortalCandidate[]) as VrPortalPick | null,
    getPortals: (): readonly VrPortalCandidate[] =>
      (options.getPortalCandidates?.() ?? []) as VrPortalCandidate[],
    pickGround: (ray, meshes): VrGroundPick | null =>
      pickGroundPoint(ray as Ray, meshes as AbstractMesh[]) as VrGroundPick | null,
    getWalkableMeshes: (): readonly unknown[] =>
      (options.getWalkableMeshes?.() ?? []) as unknown[],
    navigate: (href): void => options.navigateHref?.(href),
    // A button under the ray: the desktop pick and the desktop click handler.
    pickEntity: (ray): string | null => options.pickEntityAlongRay?.(ray) ?? null,
    clickEntity: (id): void => options.clickEntity?.(id),
    teleport,
    affordance,
    reachPortalM: PORTAL_MAX_REACH_M,
    reachTeleportM: TELEPORT_MAX_REACH_M,
  });

  const driveLocomotion = (dtMs: number): void => {
    const camera = helper.camera as WebXRCamera;
    const dt = dtMs / 1000;
    const frame = readXrInputFrame(
      helper.sessionManager?.session as XrSessionLike | undefined,
    );
    if (!frame) return;

    // TURN — rotate the XR REFERENCE SPACE/rig yaw (NOT the headset;
    // the real head still free-looks). Composing the WebXRCamera's
    // rotationQuaternion about world-up at the head; Babylon's
    // `_updateReferenceSpace` folds the delta into the reference space so it
    // persists (its own turn-feature idiom). Independent of joystick-motion.
    const yawDelta = turnController.update(frame.rightStick.x, dt);
    if (yawDelta !== 0 && camera.rotationQuaternion) {
      const yawQuat = Quaternion.RotationAxis(Vector3.UpReadOnly, yawDelta);
      camera.rotationQuaternion = yawQuat.multiply(camera.rotationQuaternion);
    }

    // MOTION — always step so GRAVITY keeps the rig grounded (even
    // with joystick-motion off — roomscale head-walking then moves only the
    // head, not the collider). When joystick-motion is on, translate in the
    // HEAD-relative direction THROUGH the desktop grounding/collision path
    // (`stepLocomotion` → `firstPersonController.moveFeetWithCollisions`), then
    // apply the collision-resolved feet DELTA to the rig so walls block / ledges
    // drop the headset by the SAME rules as desktop.
    let move = { x: 0, z: 0 };
    if (config.joystickMotion) {
      const stick = applyMotionDeadzone(frame.leftStick.x, frame.leftStick.y);
      const headYaw = camera.rotationQuaternion
        ? camera.rotationQuaternion.toEulerAngles().y
        : 0;
      // Push-up (stick.y negative in the xr-standard) = forward; stick.x = strafe.
      move = computeHorizontalMove(-stick.y, stick.x, headYaw, VR_WALK_SPEED_MPS, dt);
    }
    if (options.stepLocomotion && options.getFeetPosition) {
      const before = options.getFeetPosition();
      const after: XrVec3 = options.stepLocomotion(move.x, move.z, dt);
      camera.position.addInPlaceFromFloats(
        after.x - before.x,
        after.y - before.y,
        after.z - before.z,
      );
    }

    // ROUTE — forward the frame to the runtime's existing inputevent
    // dispatcher names (thumbstick→move, trigger→left, grip→right) via the SAME
    // host-pump→tick-drain path (NO second dispatch path).
    options.onXrInput?.(frame);

    // POINTER — per-hand `ui`/`teleport` pointing (independent of +
    // additive to the ROUTE inputevent names, like a desktop click activates a
    // portal AND fires a script pointer handler). Read the per-hand controller
    // poses + triggers off the raw XR frame and dispatch by each hand's mode.
    const hands = readXrPointerHands(
      helper.sessionManager as XrSessionManagerLike | undefined,
    );
    // Always drive the pointer (an empty list is a no-op) so a hand that drops
    // to `present:false` this frame gets its affordance cleared, not frozen.
    vrPointer.update(hands);
  };

  const controller = wireImmersiveSession(
    helper as unknown as XrHelperLike,
    options,
    WebXRState.IN_XR,
    driveLocomotion,
  );

  // Dispose the in-world pointer affordance when the session tears down
  // (exit-on-nav / Exit-VR / app teardown) — the meshes are LIFO-freed with the
  // session so no affordance leaks across a swap.
  const baseDispose = controller.dispose;
  return {
    ...controller,
    dispose(): void {
      baseDispose();
      vrPointer.clear();
      (affordance as { dispose?: () => void }).dispose?.();
    },
  };
}
