/**
 * Immersive-vr session wiring — the variant-agnostic core.
 *
 *
 * The PURE wiring over Babylon's `WebXRExperienceHelper`, expressed against a
 * STRUCTURAL `XrHelperLike` interface so it carries ZERO Babylon imports and is
 * unit-testable with a fake helper (no real WebXR in node) — the same
 * core-vs-chunk split as `sandboxCore.ts` vs `sandboxChunk.ts`. The code-split
 * `xrChunk.ts` supplies the real helper (`WebXRExperienceHelper.CreateAsync`)
 * and the `IN_XR` state constant.
 *
 * Position continuity: on enter, the XR camera is re-based at the
 * visitor's CURRENT FEET via `onInitialXRPoseSetObservable` — Babylon adds the
 * `local-floor` head height AFTER that observable, so the visitor stands at
 * their world feet with the head at feet + headHeight (no double-counted eye
 * height). On exit, the feet are handed back (horizontal from the XR camera to
 * respect room-scale walking; vertical pinned to the entry feet — the desktop
 * controller re-grounds via its probe on the next tick).
 */
import type { ImmersiveSessionController, XrSessionOptions, XrVec3 } from './xrTypes';

/** A Babylon `Observable` subset — structural so the core stays Babylon-free. */
export interface XrObservableLike<T> {
  add(cb: (value: T) => void): unknown;
  addOnce(cb: (value: T) => void): unknown;
  removeCallback(cb: (value: T) => void): unknown;
}

/** A Babylon `WebXRCamera` subset — position write + world-position read. */
export interface XrCameraLike {
  position: { set(x: number, y: number, z: number): void };
  globalPosition: { x: number; y: number; z: number };
  /** The camera's world rotation (Babylon `absoluteRotation`), for the head's yaw. */
  absoluteRotation?: { x: number; y: number; z: number; w: number };
}

/** The subset of `WebXRExperienceHelper` this wiring uses (structural). */
export interface XrHelperLike {
  state: number;
  camera: XrCameraLike;
  onStateChangedObservable: XrObservableLike<number>;
  onInitialXRPoseSetObservable: XrObservableLike<unknown>;
  enterXRAsync(sessionMode: string, referenceSpaceType: string): Promise<unknown>;
  exitXRAsync(): Promise<void>;
  dispose(): void;
}

/**
 * Build the `ImmersiveSessionController` over a helper. `inXrState` is Babylon's
 * `WebXRState.IN_XR` numeric (passed from the chunk so the core needs no enum
 * import). Deterministic: `enter`/`exit` drive `onEntered`/`onExited` at their
 * await points; the state observable drives the presenting flag + label listeners.
 */
export function wireImmersiveSession(
  helper: XrHelperLike,
  options: XrSessionOptions,
  inXrState: number,
  driveLocomotion?: (dtMs: number) => void,
): ImmersiveSessionController {
  let presenting = helper.state === inXrState;
  let disposed = false;
  let enterInFlight = false;
  let enterFeet: XrVec3 | undefined;
  const listeners = new Set<(p: boolean) => void>();

  const notify = (): void => {
    for (const l of listeners) l(presenting);
  };
  // Hand the visitor's feet back on ANY exit (Exit-VR button OR a headset-/
  // system-initiated end), computed from the STILL-LIVE camera. Fired on the
  // presenting→false transition BEFORE `notify`, so a listener that disposes us
  // on state-false (the main.ts seam) cannot make this read a disposed helper.
  const emitExited = (): void => {
    if (disposed) return;
    // Horizontal from the XR camera (respects room-scale walking); vertical
    // pinned to the entry feet (the controller re-grounds via its probe).
    const gp = helper.camera.globalPosition;
    options.onExited({ x: gp.x, y: enterFeet?.y ?? gp.y, z: gp.z });
  };
  const setPresenting = (next: boolean): void => {
    if (next !== presenting) {
      presenting = next;
      if (!next) emitExited();
      notify();
    }
  };
  const onState = (state: number): void => setPresenting(state === inXrState);
  helper.onStateChangedObservable.add(onState);

  return {
    isPresenting(): boolean {
      return presenting;
    },
    headPose() {
      if (disposed || !presenting) return null;
      const gp = helper.camera.globalPosition;
      const q = helper.camera.absoluteRotation ?? { x: 0, y: 0, z: 0, w: 1 };
      // The camera's forward (+Z) rotated by q, projected on the ground: its
      // angle from +Z toward +X is the yaw (the controller's convention).
      const fx = 2 * (q.x * q.z + q.w * q.y);
      const fz = 1 - 2 * (q.x * q.x + q.y * q.y);
      return { position: { x: gp.x, y: gp.y, z: gp.z }, yaw: Math.atan2(fx, fz) };
    },
    tick(dtMs: number): void {
      // The VR locomotion tick (turn + joystick translation +
      // XR-input routing) runs ONLY while presenting; the Babylon-touching
      // driver (gamepad read, reference-space rotate) is injected by the chunk,
      // so this core stays Babylon-free + unit-testable with a fake driver.
      if (disposed || !presenting) return;
      driveLocomotion?.(dtMs);
    },
    async enter(): Promise<void> {
      if (disposed || presenting || enterInFlight) return;
      enterInFlight = true;
      try {
        // Read the CURRENT feet and re-base the XR camera there on the initial
        // pose (local-floor adds head height afterward → feet-based origin).
        const feet = options.getFeetPosition();
        enterFeet = feet;
        helper.onInitialXRPoseSetObservable.addOnce(() => {
          helper.camera.position.set(feet.x, feet.y, feet.z);
        });
        await helper.enterXRAsync('immersive-vr', 'local-floor');
        if (disposed) return;
        setPresenting(true);
        options.onEntered();
      } finally {
        enterInFlight = false;
      }
    },
    async exit(): Promise<void> {
      if (disposed || !presenting) return;
      await helper.exitXRAsync();
      // Babylon may have already driven NOT_IN_XR (→ onExited + listeners) via
      // the state observable DURING exitXRAsync; setPresenting is idempotent, so
      // this is a no-op in that case and drives the restore otherwise.
      setPresenting(false);
    },
    onStateChange(cb: (presenting: boolean) => void): () => void {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      helper.onStateChangedObservable.removeCallback(onState);
      listeners.clear();
      // helper.dispose() tears down the session manager (ending any live
      // immersive-vr session), the WebXRCamera, the managed output canvas, and
      // the reference space — used on navigation away and on app teardown.
      helper.dispose();
      presenting = false;
    },
  };
}
